CREATE TABLE import_batches (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, fingerprint text NOT NULL UNIQUE, sources jsonb NOT NULL, imported_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE products (id text PRIMARY KEY, city text NOT NULL, name text NOT NULL, days integer NOT NULL CHECK(days BETWEEN 1 AND 10), itinerary text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', import_batch bigint REFERENCES import_batches(id));
CREATE TABLE product_days (product_id text REFERENCES products(id) ON DELETE CASCADE, day integer CHECK(day > 0), raw_text text NOT NULL, activity_names jsonb NOT NULL, PRIMARY KEY(product_id,day));
CREATE TABLE service_items (code text PRIMARY KEY, city text NOT NULL, name text NOT NULL, category text NOT NULL, unit text NOT NULL, note text NOT NULL, description text NOT NULL DEFAULT '', source_file text NOT NULL, import_batch bigint REFERENCES import_batches(id));
CREATE TABLE suppliers (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL CHECK(length(trim(name)) > 0), contact jsonb NOT NULL DEFAULT '{}', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE supplier_services (supplier_id bigint REFERENCES suppliers(id), service_code text REFERENCES service_items(code), PRIMARY KEY(supplier_id,service_code));
CREATE TABLE service_prices (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, service_code text NOT NULL REFERENCES service_items(code), supplier_id bigint REFERENCES suppliers(id), price numeric(14,2) CHECK(price >= 0), price_peak numeric(14,2) CHECK(price_peak >= 0), state text NOT NULL CHECK(state IN ('fixed','range_estimate','confirmed_free','missing')), raw_price text NOT NULL, raw_peak text NOT NULL, active boolean NOT NULL DEFAULT true, valid_from timestamptz NOT NULL DEFAULT now(), valid_to timestamptz, actor text NOT NULL, CHECK(state <> 'confirmed_free' OR (price = 0 AND price_peak = 0)));
CREATE UNIQUE INDEX service_prices_current ON service_prices(service_code) WHERE active;
CREATE TABLE product_item_names (product_id text REFERENCES products(id), kind text CHECK(kind IN ('regular','optional')), position integer CHECK(position >= 0), name text NOT NULL, PRIMARY KEY(product_id,kind,position));
CREATE TABLE product_code_refs (product_id text REFERENCES products(id), kind text CHECK(kind IN ('regular','optional')), position integer CHECK(position >= 0), service_code text REFERENCES service_items(code), PRIMARY KEY(product_id,kind,position));
CREATE TABLE cost_scopes (product_id text PRIMARY KEY REFERENCES products(id), rules jsonb NOT NULL);
CREATE TABLE route_branches (product_id text REFERENCES products(id), choice text NOT NULL, day integer NOT NULL CHECK(day > 0), position integer NOT NULL, label text NOT NULL, car_code text REFERENCES service_items(code), excluded_optional jsonb NOT NULL DEFAULT '[]', PRIMARY KEY(product_id,choice));
CREATE TABLE branch_items (product_id text, choice text, kind text CHECK(kind IN ('common','branch')), position integer CHECK(position >= 0), service_code text REFERENCES service_items(code), PRIMARY KEY(product_id,choice,kind,position), FOREIGN KEY(product_id,choice) REFERENCES route_branches(product_id,choice));
CREATE TABLE content_documents (key text PRIMARY KEY, document jsonb NOT NULL);
CREATE TABLE pricing_policies (id text PRIMARY KEY, multiplier numeric(8,4) NOT NULL CHECK(multiplier > 0), currency text NOT NULL CHECK(currency = 'CNY'), rounding text NOT NULL CHECK(rounding = 'ROUND_HALF_UP'), decimal_places integer NOT NULL CHECK(decimal_places = 2), supplier_surcharge text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), actor text NOT NULL);
CREATE UNIQUE INDEX pricing_policy_active ON pricing_policies(active) WHERE active;
CREATE TABLE audit_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, occurred_at timestamptz NOT NULL DEFAULT now(), actor text NOT NULL, operation text NOT NULL, object_key text NOT NULL, before_data jsonb, after_data jsonb);
CREATE TABLE quote_snapshots (id uuid PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), product_id text NOT NULL REFERENCES products(id), policy_id text NOT NULL REFERENCES pricing_policies(id), request_data jsonb NOT NULL, internal_cost jsonb NOT NULL, public_quote jsonb NOT NULL, service_price_versions jsonb NOT NULL, actor text NOT NULL);
CREATE VIEW current_service_costs AS SELECT s.code,s.city,s.name,s.category,s.unit,p.price,p.price_peak,p.state,p.id AS price_version,s.note FROM service_items s JOIN service_prices p ON p.service_code=s.code AND p.active;
